"""Real Windows process/HTTP tests; only loopback traffic and generated bytes."""

from __future__ import annotations

import io
import json
import os
import socket
import subprocess
import time
import wave
from collections.abc import Iterator
from contextlib import contextmanager
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from threading import Event, Thread
from typing import Any

import psutil
import pytest

from videodownloader.core.exceptions import DownloadCancelled
from videodownloader.downloader import DownloadExecutor
from videodownloader.models import (
    DownloadJob,
    DownloadOptions,
    DownloadProgress,
    DownloadStage,
    MediaItem,
    MediaKind,
    PlaylistInterval,
    Quality,
)

pytestmark = pytest.mark.integration


class MediaServer(ThreadingHTTPServer):
    daemon_threads = True

    def __init__(self, *, disconnect: bool = False) -> None:
        super().__init__(("127.0.0.1", 0), MediaHandler)
        self.payload = bytes(range(256)) * (4 * 1024 * 1024 // 256)
        self.online = Event()
        self.online.set()
        self.disconnect = disconnect
        self.get_count = 0
        self.offsets: list[int] = []
        self.requests: list[tuple[str, int]] = []
        self.disconnect_path: str | None = None
        self.extension = "mp4"
        self.content_type = "video/mp4"
        self.offline_status = 503

    @property
    def url(self) -> str:
        return f"http://127.0.0.1:{self.server_port}/sample.{self.extension}"


class MediaHandler(BaseHTTPRequestHandler):
    def log_message(self, format: str, *args: object) -> None:
        pass

    def do_HEAD(self) -> None:
        self._serve(head=True)

    def do_GET(self) -> None:
        self._serve(head=False)

    def _serve(self, *, head: bool) -> None:
        server = self.server
        assert isinstance(server, MediaServer)
        if not server.online.is_set():
            if server.offline_status:
                self.send_error(server.offline_status)
            else:
                self.connection.shutdown(socket.SHUT_RDWR)
            return
        offset = int(self.headers.get("Range", "bytes=0-").split("=")[1].split("-")[0])
        self.send_response(206 if offset else 200)
        self.send_header("Content-Type", server.content_type)
        self.send_header("Content-Length", str(len(server.payload) - offset))
        self.send_header("Accept-Ranges", "bytes")
        if offset:
            self.send_header(
                "Content-Range", f"bytes {offset}-{len(server.payload) - 1}/{len(server.payload)}"
            )
        self.end_headers()
        if head:
            return
        server.get_count += 1
        request_number = server.get_count
        server.offsets.append(offset)
        server.requests.append((self.path, offset))
        try:
            for position in range(offset, len(server.payload), 32768):
                if not server.online.is_set():
                    self.connection.shutdown(socket.SHUT_RDWR)
                    return
                self.wfile.write(server.payload[position : position + 32768])
                self.wfile.flush()
                if (
                    server.disconnect
                    and request_number >= 2
                    and position >= 512 * 1024
                    and (server.disconnect_path is None or server.disconnect_path == self.path)
                ):
                    server.disconnect = False
                    server.online.clear()
                    self.connection.shutdown(socket.SHUT_RDWR)
                    return
                time.sleep(0.015)
        except (ConnectionError, OSError):
            pass  # Extractor probes and cancelled jobs may close a socket early.


@contextmanager
def media_server(*, disconnect: bool = False) -> Iterator[MediaServer]:
    server = MediaServer(disconnect=disconnect)
    thread = Thread(target=server.serve_forever, daemon=True)
    thread.start()
    try:
        yield server
    finally:
        server.online.set()
        server.shutdown()
        server.server_close()
        thread.join(2)


def executor_and_job(tmp_path: Path, server: MediaServer) -> tuple[DownloadExecutor, DownloadJob]:
    executable = os.environ.get("VIDEODOWNLOADER_YTDLP")
    if os.name != "nt" or not executable:
        pytest.skip("Set VIDEODOWNLOADER_YTDLP on Windows for native pause/resume tests")
    yt_dlp = Path(executable)
    assert yt_dlp.is_file()
    tools = Path(os.environ.get("VIDEODOWNLOADER_FFMPEG_DIR", yt_dlp.parent))
    job = DownloadJob(
        MediaItem(server.url, "Local test", MediaKind.VIDEO),
        DownloadOptions(tmp_path, quality=Quality.BEST),
    )
    return DownloadExecutor(yt_dlp, tools, retry_delay=0.1), job


class RunningJob:
    def __init__(self, executor: DownloadExecutor, job: DownloadJob) -> None:
        self.executor = executor
        self.job = job
        self.snapshots: list[DownloadProgress] = []
        self.downloading = Event()
        self.paused = Event()
        self.outer_retry = Event()
        self.results: list[Path | None] = []
        self.errors: list[Exception] = []
        self.postprocessing_pause_results: list[bool] = []
        self.thread = Thread(target=self._run, daemon=True)

    def _progress(self, value: DownloadProgress) -> None:
        self.snapshots.append(value)
        if value.downloaded_bytes and value.downloaded_bytes >= 128 * 1024:
            self.downloading.set()
        if value.stage is DownloadStage.PAUSED:
            self.paused.set()
        if value.stage is DownloadStage.POST_PROCESSING:
            self.postprocessing_pause_results.append(self.executor.pause())
        if (
            value.stage is DownloadStage.WAITING_FOR_CONNECTION
            and value.message
            and "повтор через" in value.message
        ):
            self.outer_retry.set()

    def _run(self) -> None:
        try:
            self.results.append(self.executor.execute(self.job, self._progress))
        except Exception as error:
            self.errors.append(error)

    def __enter__(self) -> RunningJob:
        self.thread.start()
        return self

    def __exit__(self, *args: object) -> None:
        self.executor.cancel()
        self.executor.resume()
        self.thread.join(10)
        assert not self.thread.is_alive(), "Download worker did not stop"


def test_native_pause_freezes_part_file_and_resumes_same_process(tmp_path: Path) -> None:
    with media_server() as server:
        executor, job = executor_and_job(tmp_path, server)
        with RunningJob(executor, job) as run:
            assert run.downloading.wait(15), run.errors
            assert executor.pause()
            assert run.paused.wait(3), run.errors
            assert executor._process is not None
            pid = executor._process.pid
            parts = list(tmp_path.glob("*.part"))
            assert len(parts) == 1
            size = parts[0].stat().st_size
            time.sleep(0.4)
            assert parts[0].stat().st_size == size
            assert psutil.pid_exists(pid)
            executor.resume()
            assert executor._process is not None and executor._process.pid == pid
            run.thread.join(15)
            assert run.errors == []
            assert len(run.results) == 1 and run.results[0] is not None
            assert run.results[0].read_bytes() == server.payload
            assert not list(tmp_path.glob("*.part"))


def test_connection_loss_restarts_job_and_resumes_http_range(tmp_path: Path) -> None:
    with media_server(disconnect=True) as server:
        executor, job = executor_and_job(tmp_path, server)
        with RunningJob(executor, job) as run:
            assert run.outer_retry.wait(25), run.errors
            assert not server.online.is_set()
            assert list(tmp_path.glob("*.part"))
            server.online.set()
            run.thread.join(20)
            assert run.errors == []
            assert len(run.results) == 1 and run.results[0] is not None
            assert run.results[0].read_bytes() == server.payload
            assert any(offset > 0 for offset in server.offsets)
            assert any(value.stage is DownloadStage.RESUMING for value in run.snapshots)
            assert not list(tmp_path.glob("*.part"))


def test_cancel_native_paused_process_leaves_no_owned_children(tmp_path: Path) -> None:
    with media_server() as server:
        executor, job = executor_and_job(tmp_path, server)
        with RunningJob(executor, job) as run:
            assert run.downloading.wait(15), run.errors
            assert executor.pause()
            assert run.paused.wait(3), run.errors
            assert executor._process is not None
            root = psutil.Process(executor._process.pid)
            processes = [root, *root.children(recursive=True)]
            executor.cancel()
            run.thread.join(10)
            assert len(run.errors) == 1 and isinstance(run.errors[0], DownloadCancelled)
            assert run.results == []
            _, alive = psutil.wait_procs(processes, timeout=3)
            assert not alive, f"Owned processes still running: {[p.pid for p in alive]}"
            assert list(tmp_path.glob("*.part"))  # Cancel must not erase resumable data.


@pytest.mark.parametrize("archive", [False, True])
def test_selected_playlist_retry_does_not_redownload_completed_items(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    archive: bool,
) -> None:
    from videodownloader.downloader import process as process_module

    with media_server(disconnect=True) as server:
        executor, _ = executor_and_job(tmp_path, server)
        server.disconnect_path = "/3.mp4"
        entries = []
        for index in (1, 2, 3):
            url = server.url.replace("sample.mp4", f"{index}.mp4")
            entries.append(
                {
                    "id": str(index),
                    "title": f"Video {index}",
                    "extractor": "generic",
                    "extractor_key": "Generic",
                    "webpage_url": url,
                    "formats": [
                        {
                            "format_id": "http",
                            "url": url,
                            "ext": "mp4",
                            "height": 360,
                            "vcodec": "h264",
                            "acodec": "aac",
                        }
                    ],
                }
            )
        info = tmp_path / "playlist.info.json"
        info.write_text(
            json.dumps(
                {
                    "_type": "playlist",
                    "id": "playlist",
                    "title": "Local playlist",
                    "extractor": "generic",
                    "extractor_key": "Generic",
                    "entries": entries,
                }
            ),
            encoding="utf-8",
        )
        build_arguments = process_module.build_download_arguments

        def local_playlist(*args: Any) -> list[str]:
            arguments = build_arguments(*args)
            # Inject only generated metadata, not a remote playlist URL.
            return [
                *arguments[: arguments.index("--")],
                "--no-clean-info-json",
                "--load-info-json",
                str(info),
            ]

        monkeypatch.setattr(process_module, "build_download_arguments", local_playlist)
        job = DownloadJob(
            MediaItem(server.url, "Local playlist", MediaKind.PLAYLIST, item_count=3),
            DownloadOptions(
                tmp_path,
                quality=Quality.BEST,
                playlist_intervals=(PlaylistInterval(1, 1), PlaylistInterval(3, 3)),
                create_playlist_folder=False,
                use_download_archive=archive,
            ),
        )
        with RunningJob(executor, job) as run:
            assert run.outer_retry.wait(25), run.errors
            first = tmp_path / "001 - Video 1.mp4"
            assert first.read_bytes() == server.payload
            first_modified = first.stat().st_mtime_ns
            server.online.set()
            run.thread.join(20)
            assert run.errors == []
            assert len(run.results) == 1
            assert first.stat().st_mtime_ns == first_modified
            assert (tmp_path / "003 - Video 3.mp4").read_bytes() == server.payload
            assert not (tmp_path / "002 - Video 2.mp4").exists()
            assert [path for path, _ in server.requests].count("/1.mp4") == 1
            assert any(path == "/3.mp4" and offset > 0 for path, offset in server.requests)
            percentages = [
                p.overall_percent for p in run.snapshots if p.overall_percent is not None
            ]
            assert percentages == sorted(percentages)
            assert percentages[-1] == 100
            assert all(p.playlist_count == 2 for p in run.snapshots if p.playlist_count is not None)


def test_audio_pause_resumes_and_finishes_mp3_conversion(tmp_path: Path) -> None:
    with media_server() as server:
        executor, _ = executor_and_job(tmp_path, server)
        ffprobe = executor.ffmpeg_directory / "ffprobe.exe"
        if not ffprobe.is_file():
            pytest.skip("Set VIDEODOWNLOADER_FFMPEG_DIR for MP3 conversion test")
        audio = io.BytesIO()
        with wave.open(audio, "wb") as wav:
            wav.setnchannels(1)
            wav.setsampwidth(2)
            wav.setframerate(48000)
            wav.writeframes(b"\x00\x00" * (48000 * 60))
        server.payload = audio.getvalue()
        server.extension = "wav"
        server.content_type = "audio/wav"
        job = DownloadJob(
            MediaItem(server.url, "Local audio", MediaKind.VIDEO),
            DownloadOptions(tmp_path, audio_only=True),
        )
        with RunningJob(executor, job) as run:
            assert run.downloading.wait(15), run.errors
            assert executor.pause()
            assert run.paused.wait(3), run.errors
            executor.resume()
            run.thread.join(20)
            assert run.errors == []
            assert len(run.results) == 1 and run.results[0] is not None
            assert run.results[0].suffix == ".mp3"
            assert run.results[0].is_file()
            assert any(p.stage is DownloadStage.POST_PROCESSING for p in run.snapshots)
            assert run.postprocessing_pause_results
            assert not any(run.postprocessing_pause_results)
            result = subprocess.run(
                [
                    str(ffprobe),
                    "-v",
                    "error",
                    "-show_entries",
                    "format=duration",
                    "-of",
                    "json",
                    str(run.results[0]),
                ],
                capture_output=True,
                text=True,
                timeout=10,
                check=True,
            )
            assert float(json.loads(result.stdout)["format"]["duration"]) >= 60


@pytest.mark.parametrize("offline_status", [503, 0])
def test_gui_resume_while_offline_keeps_controls_and_recovers(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    qtbot: Any,
    offline_status: int,
) -> None:
    from PySide6.QtCore import Qt
    from PySide6.QtWidgets import QApplication

    from videodownloader.models import JobState
    from videodownloader.settings import AppPaths, SettingsService
    from videodownloader.tools import ToolManager
    from videodownloader.ui import AppController, MainWindow

    with media_server() as server:
        executor, _ = executor_and_job(tmp_path, server)
        server.payload *= 2
        server.offline_status = offline_status
        paths = AppPaths.from_data_dir(tmp_path / "app", tmp_path / "downloads")
        controller = AppController(paths, ToolManager(executor.ffmpeg_directory))
        window = MainWindow(controller, SettingsService(paths), auto_prepare=False)

        def before_close(widget: MainWindow) -> None:
            widget._state.reset()
            widget._explicit_exit = True
            widget._tray.hide()

        qtbot.addWidget(window, before_close_func=before_close)
        errors: list[object] = []
        controller.download_failed.connect(errors.append)
        window._set_state(JobState.ANALYZING)
        window._analysis_complete(MediaItem(server.url, "Local media", MediaKind.VIDEO))
        window._quality.setCurrentIndex(window._quality.findData(Quality.BEST))
        window.show()
        window._start_download()
        try:
            qtbot.waitUntil(
                lambda: window._current_progress.value() >= 5 or bool(errors), timeout=15000
            )
            assert not errors
            qtbot.mouseClick(window._pause, Qt.MouseButton.LeftButton)
            qtbot.waitUntil(lambda: window._state.state is JobState.PAUSED, timeout=3000)
            server.online.clear()
            # Drop the old socket while its reader is suspended.
            qtbot.wait(150)
            qtbot.mouseClick(window._pause, Qt.MouseButton.LeftButton)
            qtbot.waitUntil(
                lambda: window._state.state is JobState.WAITING_FOR_CONNECTION or bool(errors),
                timeout=15000,
            )
            assert not errors
            assert window._cancel.isEnabled()
            assert window._pause.isEnabled()
            assert controller._download_worker is not None
            assert QApplication.activeModalWidget() is None
            qtbot.wait(300)
            assert not errors
            server.online.set()
            with qtbot.waitSignal(controller.download_succeeded, timeout=35000):
                pass
            assert window._state.state is JobState.COMPLETED
            assert not errors
            assert (paths.downloads_dir / "sample.mp4").read_bytes() == server.payload
            assert any(offset > 0 for offset in server.offsets)
            qtbot.waitUntil(lambda: not controller._threads)
        finally:
            server.online.set()
            controller.cancel_download()
            qtbot.waitUntil(lambda: not controller._threads, timeout=15000)
